(() => {
 'use strict';
 const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
 const content=window.OVERDRIVE_CONTENT;
 const menu=$('.menu-toggle'),mobile=$('#mobile-nav');
 function closeMenu(){mobile.hidden=true;menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Menü öffnen');}
 menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';mobile.hidden=open;menu.setAttribute('aria-expanded',String(!open));menu.setAttribute('aria-label',open?'Menü öffnen':'Menü schließen');});
 document.addEventListener('keydown',e=>{if(e.key!=='Escape')return;const activeDialog=document.querySelector('dialog[open]');if(activeDialog){e.preventDefault();activeDialog.close();return;}if(!mobile.hidden){closeMenu();menu.focus();}},true);
 window.matchMedia('(min-width:981px)').addEventListener('change',e=>{if(e.matches)closeMenu();});
 $$('dialog').forEach(d=>{ $('[data-close-dialog]',d).addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}); });
 function normalize(s){return s.toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
 const searchEntries=[{title:'Home – Built for the next level',type:'Seite',url:'index.html'}, {title:'Apex Championship – Ablauf und Termin',type:'Turnier',url:'turnier.html'}, {title:'Teams – Simracing, Drift und Endurance',type:'Seite',url:'teams.html'}, {title:'Kontakt und Mitmachen',type:'Seite',url:'kontakt.html'},...content.news.map(n=>({title:n.title,type:n.category,url:'news-'+n.id+'.html'})),...content.teams.map(t=>({title:t.name,type:t.division,url:'teams.html?team='+encodeURIComponent(t.id)}))];
 const searchDialog=$('#search-dialog'),searchInput=$('#global-search');
 function renderSearch(){const q=normalize(searchInput.value.trim());const items=searchEntries.filter(x=>!q||normalize(x.title+' '+x.type).includes(q));const root=$('#global-results');root.replaceChildren();if(!items.length){const p=document.createElement('p');p.className='search-hint';p.textContent='Keine Treffer. Probiere „Teams“, „Turnier“ oder „Garage“.';root.append(p);return;}items.slice(0,8).forEach(x=>{const a=document.createElement('a');a.className='global-result';a.href=x.url;const type=document.createElement('span'),title=document.createElement('strong');type.textContent=x.type;title.textContent=x.title;a.append(type,title);root.append(a);});}
 $('#open-search').addEventListener('click',()=>{searchInput.value='';renderSearch();searchDialog.showModal();searchInput.focus();});searchInput.addEventListener('input',renderSearch);
 function tick(){for(const el of $$('[data-countdown]')){const diff=Math.max(0,new Date(el.dataset.countdown).getTime()-Date.now());if(!diff){el.classList.add('finished');el.textContent='Der Demo-Termin ist erreicht.';continue;}const s=Math.floor(diff/1000),values={days:Math.floor(s/86400),hours:Math.floor(s/3600)%24,minutes:Math.floor(s/60)%60,seconds:s%60};for(const [key,value]of Object.entries(values)){$('[data-time="'+key+'"]',el).textContent=String(value).padStart(2,'0');}}}
 tick();if($('[data-countdown]'))setInterval(tick,1000);
 let newsFilter='Alle';
 function filterNews(){const q=normalize($('#news-search')?.value.trim()||'');let count=0;$$('.news-grid .news-card').forEach(card=>{const visible=(newsFilter==='Alle'||card.dataset.category===newsFilter)&&(!q||normalize(card.dataset.search).includes(q));card.hidden=!visible;if(visible)count++;});if($('#news-count'))$('#news-count').textContent=count+' '+(count===1?'Artikel':'Artikel');if($('#news-empty'))$('#news-empty').hidden=count!==0;}
 $$('[data-news-filter]').forEach(button=>button.addEventListener('click',()=>{newsFilter=button.dataset.newsFilter;$$('[data-news-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});filterNews();}));$('#news-search')?.addEventListener('input',filterNews);
 $$('[data-team-filter]').forEach(button=>button.addEventListener('click',()=>{const division=button.dataset.teamFilter;$$('[data-team-filter]').forEach(b=>{const active=b===button;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$$('[data-division]').forEach(a=>{a.hidden=division!=='Alle'&&a.dataset.division!==division;});}));
 function teamProfile(id){const t=content.teams.find(t=>t.id===id);if(!t)return;const root=$('#team-dialog-content');root.replaceChildren();const img=document.createElement('img');img.src='assets/images/'+t.image+'.webp';img.alt='Motiv zum fiktiven Team '+t.name;img.className='team-dialog-image';const kicker=document.createElement('span');kicker.className='eyebrow';kicker.textContent=t.division+' / OVERDRIVE GRID';const title=document.createElement('h2');title.id='team-dialog-title';title.className='team-dialog-title';title.textContent=t.name;const p=document.createElement('p');p.textContent=t.description;const ul=document.createElement('ul');ul.className='roster';t.members.forEach((name,i)=>{const li=document.createElement('li'),num=document.createElement('span'),person=document.createElement('strong');num.className='number';num.textContent=String(i+1).padStart(2,'0');person.textContent=name;li.append(num,person);ul.append(li);});const link=document.createElement('a');link.className='button primary';link.href='kontakt.html?anliegen=Mitmachen&team='+encodeURIComponent(t.name);link.textContent='Für dieses Team interessieren ↗';const note=document.createElement('p');note.className='team-dialog-note';note.textContent='Fiktives Teamprofil · Namen und Bilder sind Demo-Inhalte.';root.append(img,kicker,title,p,ul,link,note);$('#team-dialog').showModal();}
 $$('[data-team]').forEach(b=>b.addEventListener('click',()=>teamProfile(b.dataset.team)));
 const params=new URLSearchParams(location.search);if(document.body.dataset.page==='teams'&&params.has('team'))teamProfile(params.get('team'));
 const form=$('#contact-form');let draft='';
 if(form){const subject=params.get('anliegen');if([...form.elements.subject.options].some(o=>o.value===subject))form.elements.subject.value=subject;const team=params.get('team');if(team&&content.teams.some(t=>t.name===team))form.elements.message.value='Ich interessiere mich für '+team+'.\n\n';
 form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);draft='OVERDRIVE – LOKALER DEMO-ANFRAGEENTWURF\nNicht versendet.\n\nName: '+String(data.get('name')).trim()+'\nE-Mail: '+String(data.get('email')).trim()+'\nAnliegen: '+data.get('subject')+'\n\nNachricht:\n'+String(data.get('message')).trim()+'\n';$('#draft-text').value=draft;$('#draft-result').hidden=false;$('#form-status').textContent='Dein Entwurf ist erstellt. Es wurde nichts versendet.';$('#draft-result').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth',block:'nearest'});});
 $('#download-draft').addEventListener('click',()=>{if(!draft)return;const blob=new Blob([draft],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Overdrive-Anfrageentwurf.txt';document.body.append(a);a.click();a.remove();$('#download-draft').focus({preventScroll:true});setTimeout(()=>URL.revokeObjectURL(url),1000);$('#form-status').textContent='Der Entwurf wurde zum Herunterladen bereitgestellt. Noch nichts versendet.';});
 $('#copy-draft').addEventListener('click',async()=>{if(!draft)return;try{await navigator.clipboard.writeText(draft);$('#form-status').textContent='Der Entwurf wurde kopiert. Noch nichts versendet.';}catch{$('#draft-text').focus();$('#draft-text').select();$('#form-status').textContent='Bitte den markierten Entwurf mit Strg+C oder über das Auswahlmenü kopieren.';}});
 }
})();


